
.play-shell {
  --tone-900: rgba(9, 16, 29, 0.9);
  --tone-800: rgba(18, 28, 44, 0.75);
  --tone-700: rgba(30, 41, 59, 0.6);
  --tone-600: rgba(71, 85, 105, 0.4);
  --accent: rgba(251, 146, 60, 0.8);
  --accent-soft: rgba(251, 191, 36, 0.25);
  --edge: rgba(226, 232, 240, 0.25);
  --text-main: #fff7ed;
  --text-dim: #fed7aa;
  width: 100%;
  aspect-ratio: 4 / 7;
  font-family: 'MiSans', 'HarmonyOS Sans SC', 'Source Han Sans SC', 'PingFang SC', sans-serif;
  background:
    radial-gradient(120% 120% at 12% 0%, rgba(251, 146, 60, 0.18), transparent 45%),
    radial-gradient(120% 120% at 88% 0%, rgba(244, 63, 94, 0.12), transparent 55%),
    linear-gradient(150deg, rgba(58, 35, 24, 0.88), rgba(28, 18, 16, 0.92));
  border: 1px solid rgba(251, 191, 36, 0.22);
  border-radius: 20px;
  box-shadow: 0 18px 46px rgba(24, 12, 8, 0.55), inset 0 1px 0 rgba(255, 237, 213, 0.1);
  backdrop-filter: blur(18px);
  padding: 14px;
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto;
  gap: 12px;
  position: relative;
}

.play-shell::before {
  content: '';
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: 20px;
  background: linear-gradient(140deg, rgba(251, 191, 36, 0.4), rgba(253, 230, 138, 0.08), rgba(244, 63, 94, 0.2));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

.play-shell::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(255, 237, 213, 0.1), transparent 40%);
  pointer-events: none;
}

.play-side {
  grid-column: 1 / 2;
  grid-row: 1 / 4;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 10px 8px;
  border-radius: 18px;
  border: 1px solid rgba(251, 191, 36, 0.22);
  background:
    radial-gradient(120% 120% at 30% 0%, rgba(251, 146, 60, 0.18), transparent 55%),
    linear-gradient(160deg, rgba(58, 35, 24, 0.78), rgba(28, 18, 16, 0.9));
  box-shadow: 0 18px 44px rgba(24, 12, 8, 0.55);
  backdrop-filter: blur(16px);
}

.side-btn {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  border: 1px solid rgba(251, 191, 36, 0.22);
  background: rgba(0, 0, 0, 0.18);
  color: rgba(255, 237, 213, 0.92);
  display: grid;
  place-items: center;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.side-btn.active {
  border-color: rgba(251, 146, 60, 0.62);
  background: rgba(251, 146, 60, 0.16);
  box-shadow: 0 14px 30px rgba(251, 146, 60, 0.16);
}

.side-btn:hover {
  transform: translateY(-1px);
  border-color: rgba(251, 146, 60, 0.45);
}

.side-spacer {
  flex: 1;
  width: 100%;
}

.play-main {
  grid-column: 2 / 3;
  grid-row: 1 / 4;
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 12px;
  min-width: 0;
}

.play-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 18px;
  border: 1px solid rgba(251, 191, 36, 0.22);
  background:
    radial-gradient(120% 120% at 0% 0%, rgba(251, 146, 60, 0.16), transparent 55%),
    linear-gradient(150deg, rgba(58, 35, 24, 0.9), rgba(28, 18, 16, 0.94));
  box-shadow: 0 16px 36px rgba(24, 12, 8, 0.5), inset 0 1px 0 rgba(255, 237, 213, 0.12);
  backdrop-filter: blur(18px);
}

.topbar-title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  color: rgba(255, 237, 213, 0.92);
}

.topbar-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-radius: 999px;
  border: 1px solid rgba(251, 191, 36, 0.2);
  background: rgba(24, 12, 8, 0.18);
  color: rgba(255, 237, 213, 0.92);
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}

.topbar-toggle:hover {
  border-color: rgba(251, 146, 60, 0.45);
  background: rgba(251, 146, 60, 0.12);
}

.chip-label {
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 90px;
}

.play-log-card {
  border-radius: 18px;
  border: 1px solid rgba(251, 191, 36, 0.22);
  background:
    radial-gradient(120% 120% at 20% 0%, rgba(251, 146, 60, 0.14), transparent 45%),
    linear-gradient(160deg, rgba(44, 26, 20, 0.75), rgba(62, 34, 22, 0.55));
  padding: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  position: relative;
  overflow: hidden;
}

.play-log-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: var(--play-log-bg-image, none);
  background-size: cover;
  background-position: center;
  opacity: 0.75;
  filter: blur(2px);
  transform: scale(1.05);
  pointer-events: none;
}

.play-log-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--play-log-tint, rgba(0, 0, 0, 0.55));
  opacity: var(--play-log-tint-alpha, 0.6);
  pointer-events: none;
}

.play-log-head {
  padding: 10px 12px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.play-log-title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  color: var(--text-main);
  position: relative;
  z-index: 1;
}

.play-log-content {
  padding: 12px;
  font-size: 16px;
  line-height: 1.85;
  color: rgba(255, 255, 255, 0.96);
  text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.55);
  flex: 1;
  overflow-y: auto;
  overscroll-behavior: contain;
  position: relative;
  z-index: 1;
}

.play-rightdock {
  grid-column: 3 / 4;
  grid-row: 1 / 4;
  width: 0;
  overflow: hidden;
  transition: width 0.2s ease, opacity 0.2s ease;
  opacity: 0;
  padding: 0;
}

.play-rightdock.open {
  width: 140px;
  opacity: 1;
  padding: 8px 6px;
}

.play-rightdock {
  border-radius: 18px;
  border: 1px solid rgba(251, 191, 36, 0.22);
  background:
    radial-gradient(120% 120% at 70% 0%, rgba(251, 146, 60, 0.18), transparent 55%),
    linear-gradient(160deg, rgba(58, 35, 24, 0.8), rgba(28, 18, 16, 0.92));
  box-shadow: 0 18px 44px rgba(24, 12, 8, 0.55);
  backdrop-filter: blur(16px);
}

.rightdock-head {
  font-size: 12px;
  font-weight: 700;
  color: rgba(255, 237, 213, 0.85);
  padding: 8px 8px 4px;
}

.rightdock-items {
  display: grid;
  gap: 8px;
  padding: 4px 6px 8px;
}

.rightdock-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-radius: 14px;
  border: 1px solid rgba(251, 191, 36, 0.2);
  background: rgba(24, 12, 8, 0.18);
  color: rgba(255, 237, 213, 0.92);
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}

.rightdock-btn:hover {
  border-color: rgba(251, 146, 60, 0.45);
  background: rgba(251, 146, 60, 0.12);
}

.play-input {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.play-input-field {
  width: 100%;
  border-radius: 14px;
  border: 1px solid rgba(251, 191, 36, 0.25);
  background: linear-gradient(140deg, rgba(44, 26, 20, 0.8), rgba(62, 34, 22, 0.72));
  padding: 12px 14px;
  color: var(--text-main);
  font-size: 13px;
  outline: none;
}

.play-input-field:focus {
  border-color: rgba(251, 146, 60, 0.6);
  box-shadow: 0 0 0 2px rgba(251, 146, 60, 0.25);
}

.play-send {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 14px;
  padding: 12px 16px;
  border: 1px solid rgba(251, 146, 60, 0.45);
  background: linear-gradient(135deg, rgba(251, 146, 60, 0.95), rgba(244, 63, 94, 0.85));
  color: #fff7ed;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.play-send:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.play-send:not(:disabled):hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 24px rgba(251, 146, 60, 0.35);
}

@media (max-width: 768px) {
  .play-shell {
    border-radius: 12px;
    grid-template-columns: 54px minmax(0, 1fr) auto;
  }
  .chip-label {
    display: none;
  }
  .play-input {
    grid-template-columns: 1fr;
  }
  .play-send {
    justify-content: center;
  }
  .play-rightdock.open {
    width: 110px;
  }
}
