
.mini-panel {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 5100;
  width: min(320px, 92vw);
  border-radius: 18px;
  border: 1px solid rgba(59, 130, 246, 0.25);
  background: linear-gradient(135deg, rgba(2, 6, 23, 0.96), rgba(15, 23, 42, 0.98));
  box-shadow: 0 25px 50px rgba(15, 23, 42, 0.55);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mini-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.mini-title {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #e2e8f0;

  i {
    color: #93c5fd;
  }

  .material-symbols-outlined {
    color: #93c5fd;
  }
}

.mini-title .title {
  font-size: 13px;
  font-weight: 700;
}

.mini-title .sub {
  font-size: 11px;
  color: rgba(148, 163, 184, 0.7);
}

.mini-actions {
  display: flex;
  gap: 6px;
}

.mini-btn {
  border-radius: 10px;
  padding: 5px 7px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(30, 41, 59, 0.6);
  color: #e2e8f0;
  font-size: 10px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.mini-btn.danger {
  border-color: rgba(239, 68, 68, 0.35);
  color: #fecaca;
}

.mini-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.mini-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 10px;
  padding: 5px 9px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  background: rgba(15, 23, 42, 0.85);
  color: rgba(226, 232, 240, 0.8);
  font-size: 10px;
  font-weight: 600;
}

.mini-tab.active {
  border-color: rgba(59, 130, 246, 0.5);
  background: rgba(59, 130, 246, 0.2);
  color: #e0f2fe;
}

.mini-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mini-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

@media (max-width: 640px) {
  .mini-panel {
    right: 10px;
    left: 10px;
    bottom: 10px;
    width: auto;
    border-radius: 16px;
  }
}
