
.history-overlay {
  position: fixed;
  inset: 0;
  z-index: 5000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(4, 5, 12, 0.6);
}

.history-panel {
  width: min(980px, 100%);
  max-height: min(90vh, 860px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 22px;
}

.history-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header-icon {
  width: 40px;
  height: 40px;
  border-radius: 14px;
  background: rgba(127, 19, 236, 0.2);
  color: rgba(216, 180, 254, 0.95);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.header-title {
  font-size: 16px;
  font-weight: 700;
  color: #f8fafc;
}

.header-sub {
  font-size: 12px;
  color: rgba(148, 163, 184, 0.85);
}

.header-actions {
  display: flex;
  gap: 10px;
}

.ghost-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #e2e8f0;
  font-size: 12px;
}

.history-body {
  padding: 16px 18px 20px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.loading-state,
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 40px 12px;
  text-align: center;
  color: rgba(226, 232, 240, 0.7);
}

.spinner {
  width: 24px;
  height: 24px;
  border: 3px solid rgba(226, 232, 240, 0.2);
  border-top-color: rgba(127, 19, 236, 0.8);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

.history-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.history-item {
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 18px;
  text-align: left;
}

.history-thumb {
  width: 64px;
  height: 64px;
  border-radius: 14px;
}

.history-info {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.history-name {
  font-size: 14px;
  font-weight: 700;
  color: #fff;
}

.history-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.history-tag {
  font-size: 10px;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(127, 19, 236, 0.2);
  color: rgba(216, 180, 254, 0.95);
}

.history-price {
  font-size: 14px;
  font-weight: 700;
  color: #facc15;
}

.chevron {
  color: rgba(148, 163, 184, 0.8);
}

.history-detail {
  display: grid;
  gap: 14px;
}

.detail-hero {
  width: 100%;
  height: 180px;
  border-radius: 16px;
  overflow: hidden;
}

.detail-card {
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.05);
  padding: 14px;
}

.detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.detail-title {
  font-size: 15px;
  font-weight: 700;
  color: #e2e8f0;
}

.detail-sub {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
  margin-top: 4px;
}

.detail-price {
  font-size: 18px;
  font-weight: 800;
  color: #fcd34d;
}

.detail-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.tag-chip {
  font-size: 11px;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(127, 19, 236, 0.2);
  color: rgba(216, 180, 254, 0.95);
}

.detail-section {
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  padding: 12px;
}

.section-title {
  font-size: 12px;
  font-weight: 700;
  color: rgba(226, 232, 240, 0.6);
  margin-bottom: 10px;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.stat-card {
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.05);
  padding: 10px;
  text-align: center;
}

.stat-label {
  font-size: 10px;
  color: rgba(226, 232, 240, 0.5);
  margin-bottom: 6px;
}

.stat-value {
  font-size: 14px;
  font-weight: 700;
  color: #e2e8f0;
}

.detail-actions,
.panel-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.btn-ghost,
.btn-primary {
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  color: #e2e8f0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.btn-primary {
  border-color: rgba(127, 19, 236, 0.4);
  background: linear-gradient(135deg, rgba(127, 19, 236, 0.9), rgba(139, 92, 246, 0.9));
  color: #fff;
}

.overlay-surface {
  position: fixed;
  inset: 0;
  z-index: 5100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(3, 4, 12, 0.7);
}

.reorder-panel,
.remark-panel {
  width: min(720px, 100%);
  border-radius: 20px;
  overflow: hidden;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.panel-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.reorder-card {
  padding: 12px;
  border-radius: 16px;
}

.reorder-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.reorder-title {
  font-size: 14px;
  font-weight: 700;
}

.reorder-sub {
  font-size: 12px;
  color: rgba(226, 232, 240, 0.6);
}

.reorder-price {
  font-size: 16px;
  font-weight: 700;
  color: #fcd34d;
}

.reorder-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}

.feature-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.feature-chip {
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  color: #e2e8f0;
  font-size: 11px;
  padding: 4px 10px;
}

.remark-input {
  width: 100%;
  min-height: 120px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(10, 12, 22, 0.6);
  color: #fff;
  padding: 12px;
  font-size: 13px;
  outline: none;
}

.copied-hint {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: rgba(226, 232, 240, 0.7);
}

.spin {
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 720px) {
  .history-item {
    grid-template-columns: auto 1fr;
    grid-auto-rows: auto;
  }

  .history-price,
  .chevron {
    display: none;
  }
}
